-- =============================================================================
-- REGISTROACTIVIDAD: bitácora de altas, bajas y cierres automáticos de abrazos.
-- Es lo mismo que hace la migración 20261101192034_RegistroActividad (que corre sola
-- al arrancar el backend). Este script sirve para correrlo a mano si hiciera falta.
-- Idempotente: se puede ejecutar más de una vez.
-- =============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS "REGISTROACTIVIDAD" (
    "idRegistroActividad" integer GENERATED BY DEFAULT AS IDENTITY,
    "fechaHora" timestamp without time zone NOT NULL,
    "tipoMovimiento" text NOT NULL,          -- Alta | Baja | Cierre automático
    "tipoRegistro" text NOT NULL,            -- Madre | Bebé | Voluntaria | Insumo | Proveedor | Sala | Asignación
    "idRegistro" integer NOT NULL,
    "descripcion" text NOT NULL,
    "idVoluntariaResponsable" integer NULL,  -- NULL = lo hizo el sistema (cierre diario)
    "nombreResponsable" text NULL,
    CONSTRAINT "PK_REGISTROACTIVIDAD" PRIMARY KEY ("idRegistroActividad")
);

CREATE INDEX IF NOT EXISTS "IX_REGISTROACTIVIDAD_fechaHora"
    ON "REGISTROACTIVIDAD" ("fechaHora");

CREATE INDEX IF NOT EXISTS "IX_REGISTROACTIVIDAD_tipoRegistro_idRegistro"
    ON "REGISTROACTIVIDAD" ("tipoRegistro", "idRegistro");

-- Marca la migración como aplicada para que EF no intente correrla de nuevo.
INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261101192034_RegistroActividad', '8.0.0')
ON CONFLICT ("MigrationId") DO NOTHING;

COMMIT;

